import { pool, transaction } from '../../../packages/database/src/pool.js';

export type ErasureStatus = 'pending' | 'processing' | 'failed' | 'completed';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: ErasureStatus;
  attempts: number;
  last_error: string | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export interface ClaimedErasureRequest extends ErasureRequestRow {
  available_at: Date;
}

const LEASE_SECONDS = 120;

/** Repository for customer data deletion requests and the destructive/anonymizing cleanup they drive. */
export class ErasureRepository {
  async create(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
  ): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(merchant_id,customer_id,status)
       VALUES($1,$2,'pending')
       ON CONFLICT (customer_id) DO UPDATE SET updated_at=now()
       RETURNING id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at`,
      [merchantId, customerId],
    );
    return result.rows[0]!;
  }

  async findByCustomer(merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at
       FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at
       FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async nudgeRetry(merchantId: string, requestId: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET available_at=now(), updated_at=now()
       WHERE merchant_id=$1 AND id=$2 AND status='failed'`,
      [merchantId, requestId],
    );
  }

  async recoverExpiredLeases(): Promise<number> {
    const result = await pool.query(
      `UPDATE customers.erasure_requests
       SET status='failed', last_error=COALESCE(last_error,'erasure_lease_expired'),
           attempts=attempts+1, available_at=now(),
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL, updated_at=now()
       WHERE status='processing' AND lease_expires_at<now()`,
    );
    return result.rowCount ?? 0;
  }

  async claim(workerId: string): Promise<ClaimedErasureRequest | undefined> {
    return await transaction(async (client) => {
      const result = await client.query<ClaimedErasureRequest>(
        `UPDATE customers.erasure_requests
         SET status='processing', attempts=attempts+1,
             locked_by=$1, locked_at=now(), lease_expires_at=now()+($2 || ' seconds')::interval,
             last_error=NULL, updated_at=now()
         WHERE id=(SELECT id FROM customers.erasure_requests
           WHERE status IN ('pending','failed') AND available_at<=now()
           ORDER BY available_at, created_at FOR UPDATE SKIP LOCKED LIMIT 1)
         RETURNING id,merchant_id,customer_id,status,attempts,last_error,created_at,updated_at,completed_at,available_at`,
        [workerId, LEASE_SECONDS],
      );
      return result.rows[0];
    });
  }

  async markCompleted(client: pg.PoolClient, requestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='completed', completed_at=now(), available_at=now(),
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL, last_error=NULL, updated_at=now()
       WHERE id=$1`,
      [requestId],
    );
  }

  async markFailed(
    client: pg.PoolClient,
    requestId: string,
    errorCode: string,
  ): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='failed', last_error=$2,
           available_at=now()+((LEAST(8, attempts)) || ' seconds')::interval,
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL, updated_at=now()
       WHERE id=$1`,
      [requestId, errorCode],
    );
  }

  /**
   * Removes customer personal data from the database while preserving the financial
   * meaning of retained payment, invoice, and ledger records. Idempotent: re-running
   * against an already-erased customer is a no-op.
   */
  async eraseCustomerData(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await this.redactCustomerProfile(client, customerId);
    await this.eraseCustomerPiiRecords(client, customerId);
    await this.redactProviderCustomerMirror(client, customerId);
    await this.redactFinancialSnapshots(client, customerId);
    await this.eraseOperationalCustomerData(client, customerId);
    await this.redactEventPayloads(client, customerId);
    await this.recordErasureAudit(client, merchantId, customerId);
  }

  private async redactCustomerProfile(client: pg.PoolClient, customerId: string): Promise<void> {
    await client.query(
      `UPDATE customers.customers
       SET email='erased:'||id::text||'@erased.local',
           name='Erased customer',
           phone=NULL,
           external_reference='erased:'||id::text,
           metadata='{}'::jsonb,
           status='erased',
           version=version+1,
           updated_at=now()
       WHERE id=$1`,
      [customerId],
    );
  }

  private async eraseCustomerPiiRecords(client: pg.PoolClient, customerId: string): Promise<void> {
    await client.query(`DELETE FROM customers.support_messages WHERE author_id=$1`, [customerId]);
    await client.query(
      `DELETE FROM customers.support_tickets WHERE merchant_id=(SELECT merchant_id FROM customers.customers WHERE id=$1)
         AND NOT EXISTS (SELECT 1 FROM customers.support_participants p WHERE p.ticket_id=customers.support_tickets.id)`,
      [customerId],
    );
    await client.query(
      `DELETE FROM customers.support_participants WHERE customer_id=$1 OR ticket_id IN (
         SELECT t.id FROM customers.support_tickets t
         JOIN customers.support_participants p ON p.ticket_id=t.id WHERE p.customer_id=$1)`,
      [customerId],
    );
    await client.query(`DELETE FROM customers.payment_method_refs WHERE customer_id=$1`, [customerId]);
    await client.query(`DELETE FROM customers.contacts WHERE customer_id=$1`, [customerId]);
    await client.query(`DELETE FROM customers.addresses WHERE customer_id=$1`, [customerId]);
    await client.query(`DELETE FROM customers.provider_customer_mappings WHERE customer_id=$1`, [customerId]);
    await client.query(`DELETE FROM customers.customer_imports WHERE customer_id=$1`, [customerId]);
  }

  private async redactProviderCustomerMirror(client: pg.PoolClient, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM provider_sandbox.customers WHERE payflow_customer_id=$1`,
      [customerId],
    );
  }

  private async redactFinancialSnapshots(client: pg.PoolClient, customerId: string): Promise<void> {
    await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot=jsonb_build_object('customerId',customer_id,'redacted',true), updated_at=now()
       WHERE customer_id=$1`,
      [customerId],
    );
    await client.query(
      `UPDATE payments.refunds
       SET customer_email=NULL
       WHERE payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE customer_id=$1)`,
      [customerId],
    );
    await client.query(
      `UPDATE payments.invoices
       SET billing_snapshot=jsonb_build_object('customerId',customer_id,'redacted',true)
       WHERE customer_id=$1`,
      [customerId],
    );
  }

  private async eraseOperationalCustomerData(client: pg.PoolClient, customerId: string): Promise<void> {
    await client.query(`DELETE FROM operations.analytics_events WHERE customer_id=$1`, [customerId]);
    await client.query(`DELETE FROM operations.notification_preferences WHERE customer_id=$1`, [customerId]);
    await client.query(`DELETE FROM operations.notifications WHERE customer_id=$1`, [customerId]);
    await client.query(`DELETE FROM operations.email_deliveries WHERE customer_id=$1`, [customerId]);
    await client.query(
      `DELETE FROM operations.dead_letters
       WHERE source='email_delivery' AND payload->>'customerId'=$1`,
      [customerId],
    );
    await client.query(
      `UPDATE operations.jobs
       SET payload=jsonb_set(payload,'{customerSnapshot}',jsonb_build_object('redacted',true),false)
       WHERE payload->>'customerId'=$1`,
      [customerId],
    );
    await client.query(
      `UPDATE operations.audit_logs
       SET metadata='{}'::jsonb
       WHERE target_type='customer' AND target_id=$1`,
      [customerId],
    );
  }

  private async redactEventPayloads(client: pg.PoolClient, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.outbox_events
       SET payload=(payload - 'email' - 'name' - 'phone' - 'customerEmail' - 'customerName'
                         - 'externalReference' - 'metadata' - 'billingName')
       WHERE aggregate_type='customer' AND aggregate_id=$1`,
      [customerId],
    );
    await client.query(
      `UPDATE operations.outbox_events
       SET payload=(payload - 'customerEmail' - 'email')
       WHERE payload->>'customerId'=$1`,
      [customerId],
    );
    await client.query(
      `DELETE FROM operations.dead_letters
       WHERE source='outbox_event'
         AND source_id IN (SELECT id FROM operations.outbox_events WHERE aggregate_id=$1 AND aggregate_type='customer')`,
      [customerId],
    );
  }

  private async recordErasureAudit(client: pg.PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `INSERT INTO platform.audit_logs(merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
       VALUES($1,'api_key','customer',$2,'customer.erased','{}'::jsonb,gen_random_uuid())`,
      [merchantId, customerId],
    );
  }
}
