{"command": "create", "file_text": "import { createHash } from 'node:crypto';
import { Redis } from 'ioredis';
import { v4 as uuid } from 'uuid';
import { config } from '../../../packages/config/src/index.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import {
  ErasureRepository,
  type ErasureRequestRow,
} from './erasure-repository.js';
import { CustomerRepository } from './repository.js';

export interface ErasureRequestResponse {
  id: string;
  customerId: string;
  status: string;
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

const ERASURE_EVENT_TYPE = 'customer.erasure.requested.v1';

export function serializeErasureRequest(row: ErasureRequestRow): ErasureRequestResponse {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

function requestHash(customerId: string): string {
  return createHash('sha256').update(JSON.stringify({ customerId })).digest('hex');
}

/** Orchestrates customer data deletion requests and the asynchronous cleanup workflow. */
export class ErasureService {
  private readonly redis = new Redis(config().REDIS_URL);

  constructor(
    private readonly repository = new ErasureRepository(),
    private readonly customers = new CustomerRepository(),
  ) {}

  async createRequest(merchantId: string, customerId: string, idempotencyKey: string): Promise<{ status: number; body: ErasureRequestResponse }> {
    const customer = await this.customers.find(merchantId, customerId);
    if (!customer) return { status: 404, body: { id: '', customerId, status: 'not_found', attempts: 0, createdAt: new Date(0).toISOString(), updatedAt: new Date(0).toISOString(), completedAt: null, lastError: 'customer_not_found' } };

    const hash = requestHash(customerId);
    const result = await transaction(async (client) => {
      const replay = await this.reserveIdempotency(client, merchantId, idempotencyKey, hash);
      if (replay) return { replay };
      const existing = await this.repository.findByCustomer(merchantId, customerId);
      if (existing) {
        const body = serializeErasureRequest(existing);
        await this.completeIdempotency(client, merchantId, idempotencyKey, 202, body);
        return { created: existing };
      }
      const created = await this.repository.create(client, merchantId, customerId);
      await addOutboxEvent(client, {
        eventType: ERASURE_EVENT_TYPE, aggregateType: 'erasure_request', aggregateId: created.id,
        merchantId, correlationId: uuid(), payload: { requestId: created.id, customerId, status: 'pending' },
      });
      const body = serializeErasureRequest(created);
      await this.completeIdempotency(client, merchantId, idempotencyKey, 202, body);
      return { created };
    });

    if ('replay' in result) {
      return { status: result.replay!.status, body: result.replay!.body as ErasureRequestResponse };
    }
    return { status: 202, body: serializeErasureRequest(result.created!) };
  }

  async getRequest(merchantId: string, requestId: string): Promise<ErasureRequestResponse | undefined> {
    const row = await this.repository.find(merchantId, requestId);
    return row ? serializeErasureRequest(row) : undefined;
  }

  /** Claims a runnable erasure request and runs cleanup to convergence. Safe to retry. */
  async processOne(workerId: string): Promise<boolean> {
    const claimed = await this.repository.claim(workerId);
    if (!claimed) return false;
    try {
      await this.runCleanup(claimed.merchant_id, claimed.customer_id);
      await transaction(async (client) => await this.repository.markCompleted(client, claimed.id));
      logger.info({ requestId: claimed.id, customerId: claimed.customer_id }, 'erasure request completed');
    } catch (error) {
      const code = error instanceof Error ? error.message : 'erasure_failed';
      await transaction(async (client) => await this.repository.markFailed(client, claimed.id, code));
      logger.error({ error, requestId: claimed.id, customerId: claimed.customer_id }, 'erasure request failed');
    }
    return true;
  }

  async recoverExpiredLeases(): Promise<number> {
    return await this.repository.recoverExpiredLeases();
  }

  async nudgeRetry(merchantId: string, requestId: string): Promise<void> {
    await this.repository.nudgeRetry(merchantId, requestId);
  }

  private async runCleanup(merchantId: string, customerId: string): Promise<void> {
    const destinations = await this.repository.emailDeliveriesForCustomer(customerId);
    const objectKeys = await this.repository.customerObjectKeys(merchantId, customerId);
    const redactedChecksums = await this.redactStoredObjects(merchantId, objectKeys);
    await transaction(async (client) => {
      await this.repository.eraseCustomerData(client, merchantId, customerId);
      await this.repository.redactDocumentManifests(client, merchantId, customerId, redactedChecksums);
    });
    await this.purgeExternalState(merchantId, customerId, destinations);
  }

  private async redactStoredObjects(
    merchantId: string,
    objects: { objectKey: string; documentType: string; checksum: string }[],
  ): Promise<Record<string, string>> {
    const redactedChecksums: Record<string, string> = {};
    for (const item of objects) {
      const redacted = JSON.stringify({
        redacted: true,
        merchantId,
        documentType: item.documentType,
        redactedAt: new Date().toISOString(),
      });
      const checksum = createHash('sha256').update(redacted).digest('hex');
      await objectStore.putObject(DOCUMENT_BUCKET, item.objectKey, redacted, Buffer.byteLength(redacted), {
        'Content-Type': 'application/json',
      });
      redactedChecksums[item.objectKey] = checksum;
    }
    return redactedChecksums;
  }

  private async purgeExternalState(merchantId: string, customerId: string, destinations: string[]): Promise<void> {
    const cacheKey = `merchant:${merchantId}:customer:${customerId}`;
    await this.redis.del(cacheKey, `${cacheKey}:activity`);
    await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}` }).catch(() => undefined);
    for (const destination of destinations) {
      await deleteMailpitMessagesForRecipient(destination).catch((error) => {
        logger.warn({ error, destination: 'redacted' }, 'mailpit deletion deferred');
      });
    }
  }

