import test from 'node:test';
import { randomUUID } from 'node:crypto';
import { serializeErasureRequest } from '../apps/customer-service/src/erasure-service.js';
import { ErasureRepository } from '../apps/customer-service/src/erasure-repository.js';
import { transaction } from '../packages/database/src/pool.js';

const MERCHANT_ID = '10000000-0000-4000-8000-000000000001';

function makeRow(overrides: Partial<{ id: string; customer_id: string; status: string; attempts: number; last_error: string | null; completed_at: Date | null }> = {}) {
  return {
    id: overrides.id ?? randomUUID(),
    merchant_id: MERCHANT_ID,
    customer_id: overrides.customer_id ?? randomUUID(),
    status: overrides.status ?? 'pending',
    attempts: overrides.attempts ?? 0,
    last_error: overrides.last_error ?? null,
    created_at: new Date('2026-08-20T12:00:00.000Z'),
    updated_at: new Date('2026-08-20T12:00:00.000Z'),
    completed_at: overrides.completed_at ?? null,
  };
}

test('erasure request serialization matches the public API contract', () => {
  const serialized = serializeErasureRequest(makeRow({ status: 'pending' }));
  assert.deepEqual(Object.keys(serialized).sort(),
    ['attempts', 'completedAt', 'createdAt', 'customerId', 'id', 'lastError', 'status', 'updatedAt']);
  assert.equal(serialized.status, 'pending');
  assert.equal(serialized.attempts, 0);
  assert.equal(serialized.completedAt, null);
  assert.equal(serialized.lastError, null);
  assert.equal(serialized.createdAt, '2026-08-20T12:00:00.000Z');
});

test('erasure request serialization reports completion and stable error codes', () => {
  const completed = serializeErasureRequest(makeRow({ status: 'completed', completed_at: new Date('2026-08-20T12:01:00.000Z') }));
  assert.equal(completed.status, 'completed');
  assert.equal(completed.completedAt, '2026-08-20T12:01:00.000Z');
  const failed = serializeErasureRequest(makeRow({ status: 'failed', last_error: 'erasure_lease_expired' }));
  assert.equal(failed.status, 'failed');
  assert.equal(failed.lastError, 'erasure_lease_expired');
});

test('erasure request lifecycle claims pending work and converges on completed', async () => {
  const customerId = randomUUID();
  await transaction(async (client) => {
    await client.query(
      `INSERT INTO customers.customers(id,merchant_id,external_reference,email,name)
       VALUES($1,$2,$3,$4,$5) ON CONFLICT DO NOTHING`,
      [customerId, MERCHANT_ID, `erasure-test-${customerId}`, `erasure-test-${customerId}@example.test`, 'Erasure Test'],
    );
  });

  const repository = new ErasureRepository();
  await transaction(async (client) => {
    const created = await repository.create(client, MERCHANT_ID, customerId);
    assert.equal(created.status, 'pending');
    assert.equal(created.customer_id, customerId);
  });

  const claimed = await repository.claim('test-worker');
  assert.ok(claimed, 'a pending erasure request should be claimable');
  assert.equal(claimed!.status, 'processing');
  assert.equal(claimed!.attempts, 1);

