    await repository.eraseCustomerData(client, MERCHANT_ID, customerId);
    await repository.markCompleted(client, claimed!.id);
  });

  const found = await repository.find(MERCHANT_ID, claimed!.id);
  assert.equal(found?.status, 'completed');
  assert.ok(found?.completed_at);

  const profile = await transaction(async (client) => {
