{"command": "str_replace", "new_str": "  async redactDocumentManifests(client: pg.PoolClient, merchantId: string, customerId: string, redactedChecksums: Record<string, string>): Promise<void> {
    // Preserve the manifest metadata (paymentId/invoiceId/number) so retained
    // financial records keep their linkage; only the stored object's PII is
    // redacted, and the checksum is updated to match the redacted object.
    const entries = Object.entries(redactedChecksums);
    if (entries.length === 0) return;
    for (const [objectKey, checksum] of entries) {
      await client.query(
        `UPDATE operations.document_manifests SET checksum=$3
         WHERE merchant_id=$1 AND customer_id=$2 AND object_key=$4`,
        [merchantId, customerId, checksum, objectKey],
      );
    }
  }", "old_str": "  async redactDocumentManifests(client: pg.PoolClient, merchantId: string, customerId: string, redactedChecksums: Record<string, string>): Promise<void> {
